///
/// Both fields tolerate absence: `availableUserDomains` is optional in the lexicon, and
/// the `custos` extension is by definition absent on every host that is not a Custos. A
/// server that answers this endpoint at all must not be rejected over a missing optional
/// field, because the answer "this host advertises nothing" is itself the signal the
/// create-flow gate needs.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DescribeServerResponse {
    #[serde(default)]
    available_user_domains: Vec<String>,
    #[serde(default)]
    custos: Option<CustosExtension>,
}

/// Custos's namespaced `describeServer` extension.
///
/// Named capabilities rather than an "is this Custos" boolean: a self-hosted Custos may
/// run with a capability disabled, so every gate reads as "does this host advertise X?".
/// Unknown capability names are carried through untouched — the wallet asks about the one
/// it needs and ignores the rest.
#[derive(Deserialize)]
struct CustosExtension {
    #[serde(default)]
    capabilities: Vec<String>,
}

